var gaoUsbDisk=[],offlineUsbDisk=[];
function init_object_usb_disk_info()
{
var nIndex,szDiskName;
var oTmpUsbDisk={},oTmpOfflineUsbDisk={};
for(var x in mounted_lists)
{
if(x=="NULL"){
break;}
aTmp=mounted_lists[x].split("|");
if(!(aTmp.constructor===Array)){
continue;}
szDiskName=aTmp[5];
for(var ki=0;ki<gaoUsbDisk.length;ki++){
if(gaoUsbDisk[ki]["disk_name"]===szDiskName){
if(gaoUsbDisk[ki]["mounted_name"]==x.replace(/\d/,"")){
nIndex=ki;
break;}}}
if(ki>=gaoUsbDisk.length){
oTmpUsbDisk={};
if(szDiskName==="unknown"){
szDiskName=x.replace(/\d/,"");}
oTmpUsbDisk["disk_name"]=szDiskName;
oTmpUsbDisk["mounted_name"]=(aTmp[7]=="printer")?x:x.replace(/\d/,"");
oTmpUsbDisk["type"]=aTmp[7];
oTmpUsbDisk["info"]=[];
oTmpUsbDisk["folder"]=[];
oTmpUsbDisk["id"]=(aTmp.length!=9)?"":aTmp[8];
gaoUsbDisk.push(oTmpUsbDisk);
oTmpUsbDisk=null;
nIndex=gaoUsbDisk.length-1;}
oTmpUsbDisk={};
oTmpUsbDisk["share_name"]=aTmp[6];
oTmpUsbDisk["capacity"]=format_Kb_To_Gb(parseInt(aTmp[0]));
oTmpUsbDisk["used_space"]=format_Kb_To_Gb(parseInt(aTmp[1]));
oTmpUsbDisk["free_space"]=format_Kb_To_Gb(parseInt(aTmp[2]));
gaoUsbDisk[nIndex]["info"].push(oTmpUsbDisk);
oTmpUsbDisk=null;}
mounted_lists=null;
for(var ki=0;ki<(gaoUsbDisk.length-1);ki++){
for(var kj=(ki+1);kj<gaoUsbDisk.length;kj++){
if(gaoUsbDisk[kj]["mounted_name"]<gaoUsbDisk[ki]["mounted_name"]){
var oTmp=gaoUsbDisk[ki];
gaoUsbDisk[ki]=gaoUsbDisk[kj];
gaoUsbDisk[kj]=oTmp;}}}
var offline_usb_type='storage';
for(var i=0;i<ARC_DEF_USB_CLIENT_MAXNUM;i++){
oTmpOfflineUsbDisk={};
switch(getCfg("usb_type"+i)){
case"Mass Storage":
offline_usb_type='storage';
break;
case"Printer":
offline_usb_type='printer';
break;
case"CDC-Data":
offline_usb_type='modem';
break;}
if(getCfg("usb_name"+i)!=""){
oTmpOfflineUsbDisk["usb_name"]=getCfg("usb_name"+i);
oTmpOfflineUsbDisk["usb_serialnum"]=getCfg("usb_serialnum"+i);
oTmpOfflineUsbDisk["type"]=offline_usb_type;
offlineUsbDisk.push(oTmpOfflineUsbDisk);
oTmpOfflineUsbDisk=null;}}}
function format_Kb_To_Gb(kilobytes)
{
var nMegabytes;
var nGigaRemainder;
var nGigabytes;
var result;
nMegabytes=Math.floor(kilobytes/1024);
nGigaRemainder=(nMegabytes%1024);
nGigabytes=Math.floor(nMegabytes/1024);
if(nGigaRemainder>0)
{
nGigaRemainder=""+nGigaRemainder;
while(nGigaRemainder.length<3){
nGigaRemainder="0"+nGigaRemainder;}}
result=nGigabytes+"."+nGigaRemainder;
return result;}
var defroute_wan_ip="95.20.132.77";
